-- Read-only baseline checks for the 45-table projects.
SET NOCOUNT ON;
IF (SELECT COUNT(*) FROM [retail].[Customers]) <> 5 THROW 51000, 'retail.Customers: row count mismatch', 1;
IF (SELECT COUNT(*) FROM [retail].[Products]) <> 5 THROW 51000, 'retail.Products: row count mismatch', 1;
IF (SELECT COUNT(*) FROM [retail].[Orders]) <> 12 THROW 51000, 'retail.Orders: row count mismatch', 1;
IF EXISTS (SELECT 1 FROM [retail].[Orders] c LEFT JOIN [retail].[Customers] p ON c.CustomerID=p.CustomerID WHERE c.CustomerID IS NOT NULL AND p.CustomerID IS NULL) THROW 51000, 'retail.Orders: orphan reference', 1;
IF EXISTS (SELECT 1 FROM [retail].[Orders] c LEFT JOIN [retail].[Orders] p ON c.ParentOrderID=p.OrderID WHERE c.ParentOrderID IS NOT NULL AND p.OrderID IS NULL) THROW 51000, 'retail.Orders: orphan reference', 1;
IF (SELECT COUNT(*) FROM [retail].[OrderItems]) <> 6 THROW 51000, 'retail.OrderItems: row count mismatch', 1;
IF EXISTS (SELECT 1 FROM [retail].[OrderItems] c LEFT JOIN [retail].[Orders] p ON c.OrderID=p.OrderID WHERE c.OrderID IS NOT NULL AND p.OrderID IS NULL) THROW 51000, 'retail.OrderItems: orphan reference', 1;
IF EXISTS (SELECT 1 FROM [retail].[OrderItems] c LEFT JOIN [retail].[Products] p ON c.ProductID=p.ProductID WHERE c.ProductID IS NOT NULL AND p.ProductID IS NULL) THROW 51000, 'retail.OrderItems: orphan reference', 1;
IF (SELECT COUNT(*) FROM [retail].[Payments]) <> 5 THROW 51000, 'retail.Payments: row count mismatch', 1;
IF EXISTS (SELECT 1 FROM [retail].[Payments] c LEFT JOIN [retail].[Orders] p ON c.OrderID=p.OrderID WHERE c.OrderID IS NOT NULL AND p.OrderID IS NULL) THROW 51000, 'retail.Payments: orphan reference', 1;
IF EXISTS (SELECT 1 FROM sys.foreign_keys WHERE schema_id=SCHEMA_ID(N'retail') AND (is_disabled=1 OR is_not_trusted=1)) THROW 51000, 'retail: untrusted foreign key', 1;
IF (SELECT SUM(OrderTotal) FROM [retail].[Orders]) <> 1700 THROW 51000, 'retail: amount total mismatch', 1;
SELECT 'retail' AS Domain, 'PASS' AS FixtureCheck;
